575	fn kruin_outlaw_transforms_gains_double_strike_and_menace() {
576	    let reg = registry();
577	    let mut state = game_at_step(Step::Upkeep, P0);
578	    let outlaw = named_creature(&mut state, &reg, "Kruin Outlaw", P0);
579	
580	    // Front: first strike, no double strike or menace
581	    assert!(state.has_keyword(outlaw, Keyword::FirstStrike, &reg));
582	    assert!(!state.has_keyword(outlaw, Keyword::DoubleStrike, &reg));
583	    assert!(!state.has_keyword(outlaw, Keyword::Menace, &reg));
584	
585	    trigger_upkeep(&mut state, &reg);
586	
587	    // Back: double strike, "can't be blocked except by two or more creatures" for
588	    // all Werewolves (implemented as MinimumBlockers, not as Keyword::Menace).
589	    assert!(state.get_object(outlaw).unwrap().is_transformed);
590	    assert_eq!(state.effective_power(outlaw, &reg).unwrap(), 3);
591	    assert!(state.has_keyword(outlaw, Keyword::DoubleStrike, &reg),
592	        "Terror of Kruin Pass should have Double Strike");
593	    // The blocking restriction is enforced via MinimumBlockers continuous effect,
594	    // not as a menace keyword. See kruin_outlaw.rs tests for blocking validation.
595	}
596	
597	// ── Subtype tests ─────────────────────────────────────────────────
598	
599	#[test]
600	fn transformed_werewolf_has_werewolf_subtype_not_human() {
601	    let reg = registry();
602	    let mut state = game_at_step(Step::PrecombatMain, P0);
603	    let waif = named_creature(&mut state, &reg, "Reckless Waif", P0);
604	
605	    // Front face: Human subtype
606	    assert!(state.matches_filter(waif,
607	        &CreatureFilter::HasSubtype("Human".into()), P0, &reg),
608	        "Front face should have Human subtype");
609	
610	    // Transform
611	    state.get_object_mut(waif).unwrap().is_transformed = true;
612	
613	    // Back face: Werewolf subtype, not Human
614	    assert!(state.matches_filter(waif,
615	        &CreatureFilter::HasSubtype("Werewolf".into()), P0, &reg),
616	        "Back face should have Werewolf subtype");
617	    assert!(!state.matches_filter(waif,
618	        &CreatureFilter::HasSubtype("Human".into()), P0, &reg),
619	        "Back face should not have Human subtype");
620	}
621	
622	// ── All werewolves transform together ─────────────────────────────
623	
624	#[test]
625	fn multiple_werewolves_transform_on_same_upkeep() {
626	    let reg = registry();
627	    let mut state = game_at_step(Step::Upkeep, P0);
628	    let waif = named_creature(&mut state, &reg, "Reckless Waif", P0);
629	    let shepherd = named_creature(&mut state, &reg, "Gatstaf Shepherd", P0);
630	    let outcasts = named_creature(&mut state, &reg, "Grizzled Outcasts", P0);
631	
632	    // No spells cast last turn, all should transform
633	    trigger_upkeep(&mut state, &reg);
634	
635	    assert!(state.get_object(waif).unwrap().is_transformed, "Reckless Waif should transform");
636	    assert!(state.get_object(shepherd).unwrap().is_transformed, "Gatstaf Shepherd should transform");
637	    assert!(state.get_object(outcasts).unwrap().is_transformed, "Grizzled Outcasts should transform");
638	}
639	
640	#[test]
641	fn multiple_werewolves_transform_back_together() {
642	    let reg = registry();
643	    let mut state = game_at_step(Step::Upkeep, P0);
644	    let waif = named_creature(&mut state, &reg, "Reckless Waif", P0);
645	    let shepherd = named_creature(&mut state, &reg, "Gatstaf Shepherd", P0);
646	
647	    // Manually transform to werewolf side
648	    state.get_object_mut(waif).unwrap().is_transformed = true;
649	    state.get_object_mut(shepherd).unwrap().is_transformed = true;
650	
651	    // A player cast 2 spells last turn
652	    state.spells_cast_last_turn.insert(P1, 2);
653	
654	    trigger_upkeep(&mut state, &reg);
655	
656	    assert!(!state.get_object(waif).unwrap().is_transformed, "Should transform back");
657	    assert!(!state.get_object(shepherd).unwrap().is_transformed, "Should transform back");
658	}
659	
660	// ── Werewolf does not transform when shouldn't ────────────────────
661	
662	#[test]
663	fn werewolf_side_stays_if_one_spell_cast() {
664	    let reg = registry();
665	    let mut state = game_at_step(Step::Upkeep, P0);
666	    let waif = named_creature(&mut state, &reg, "Reckless Waif", P0);
667	    state.get_object_mut(waif).unwrap().is_transformed = true;
668	
669	    // Only 1 spell cast last turn: not enough to transform back
670	    state.spells_cast_last_turn.insert(P0, 1);
671	
672	    trigger_upkeep(&mut state, &reg);
673	
674	    assert!(state.get_object(waif).unwrap().is_transformed,
675	        "Werewolf should stay transformed with only 1 spell cast");
676	}
677	
678	#[test]
679	fn human_side_stays_if_any_spell_cast() {
680	    let reg = registry();
681	    let mut state = game_at_step(Step::Upkeep, P0);
682	    let waif = named_creature(&mut state, &reg, "Reckless Waif", P0);
683	
684	    // Opponent cast 1 spell last turn
685	    state.spells_cast_last_turn.insert(P1, 1);
686	
687	    trigger_upkeep(&mut state, &reg);
688	
689	    assert!(!state.get_object(waif).unwrap().is_transformed,
690	        "Human should stay on front face when any spell was cast last turn");
691	}
